package it.trisassist.vision

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

object TemplateData {
    fun load(): Map<ItemKind, Bitmap> = mapOf(
        ItemKind.CAKE to decode(""),
        ItemKind.CARROT to decode(""),
        ItemKind.CHEESE to decode(""),
        ItemKind.CORN to decode(""),
        ItemKind.CUTLERY to decode(""),
        ItemKind.GEM to decode(""),
        ItemKind.GLOVE to decode(""),
        ItemKind.HAT to decode(""),
        ItemKind.MEAT to decode(""),
        ItemKind.MILK to decode(""),
        ItemKind.PEA to decode(""),
        ItemKind.SKEWER to decode(""),
        ItemKind.SOCK to decode(""),
        ItemKind.SPROUT to decode(""),
        ItemKind.WOOL to decode(""),
        ItemKind.YARN to decode("")
    )

    private fun decode(value: String): Bitmap {
        val bytes = Base64.decode(value, Base64.DEFAULT)
        return requireNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size))
    }
}
